def TABLE(head, rows, label):
    return (f'<div class="table-scroll" tabindex="0" role="region" aria-label="{label}"><table><thead><tr>' + "".join(f'<th scope="col">{h}</th>' for h in head)
            + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</tbody></table></div>")


